<?php require __DIR__.'/config/config.php'; $site=setting('site_name','Rishtewale');
$profiles=[]; try{$q=db()->query("SELECT * FROM profiles WHERE gender='female' AND active=1 ORDER BY RAND() LIMIT 30");$profiles=$q->fetchAll();}catch(Throwable $e){}
if($_SERVER['REQUEST_METHOD']==='POST'){ $gender=$_POST['gender']??'';$age=(int)($_POST['age']??0);$name=trim($_POST['name']??'');$state=trim($_POST['state']??'');$city=trim($_POST['city']??'');$wa=trim($_POST['whatsapp']??'');$tg=trim($_POST['telegram']??''); if($age<18||!in_array($gender,['male','female'],true)||!$name||!$state||!$city||!$wa){$err='Please fill all required details. Age must be 18+';}else{$s=db()->prepare('INSERT INTO users(gender,age,name,state,city,whatsapp,telegram) VALUES(?,?,?,?,?,?,?)');$s->execute([$gender,$age,$name,$state,$city,$wa,$tg]);$_SESSION['user_id']=db()->lastInsertId();$_SESSION['gender']=$gender;$_SESSION['city']=$city;$_SESSION['state']=$state;header('Location: dashboard.php');exit;}}
?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($site)?></title><link rel="stylesheet" href="assets/style.css"></head><body><main class="phone"><header><b>💗 <?=h($site)?></b><span>● Online</span></header><section class="hero"><div class="pill"><?=count($profiles)?>+ Profiles</div><h1>Find Someone Special</h1><p><?=h(setting('tagline'))?></p><div class="slider"><?php foreach(array_slice($profiles,0,6) as $p):?><div class="mini"><div class="avatar">👩</div><b><?=h($p['name'])?></b><small><?=h($p['city'])?></small></div><?php endforeach;?></div></section><section class="card"><h2>Register / पंजीकरण</h2><?php if(!empty($err)):?><div class="error"><?=h($err)?></div><?php endif;?><form method="post"><label>आप कौन हैं?</label><div class="gender"><label><input type="radio" name="gender" value="male" required> 👨 Male</label><label><input type="radio" name="gender" value="female"> 👩 Female</label></div><input name="age" type="number" min="18" max="100" placeholder="Your Age / उम्र" required><input name="name" placeholder="Name / नाम" required><select name="state" required><option value="">State / राज्य</option><?php foreach(['Uttar Pradesh','Delhi','Maharashtra','Bihar','Rajasthan','Madhya Pradesh','Haryana','Punjab','Gujarat','West Bengal','Uttarakhand','Other'] as $x):?><option><?=h($x)?></option><?php endforeach;?></select><input name="city" placeholder="City / शहर" required><input name="whatsapp" placeholder="WhatsApp Number" required><input name="telegram" placeholder="Telegram Username (optional)"><button>Continue →</button></form></section></main><script src="/rishtewale-protection.js"></script>
</body></html>
